import React, { useState } from 'react';
import './JudgeLogin.css';

const JudgeLogin = ({ 
  onJudgeLogin, 
  setShowJudgeLogin, 
  setIsAdmin, 
  setShowAuth, 
  setCurrentJudge, 
  setAuthPin 
}) => {
  const [pin, setPin] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showJudgeLogin, setShowJudgeLoginState] = useState(false);
  const [showInfoModal, setShowInfoModal] = useState(false);

  const handleLogin = async (e) => {
    e.preventDefault();

    if (!pin.trim()) {
      setError(language === 'tl' ? 'Mangyaring kang PIN' : 'Please enter your PIN');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Call appropriate login API based on login type
      const response = await fetch('http://localhost/Tabolator_Casestudy/backend/api/judge-login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ pin }),
      });

      const data = await response.json();

      if (data.success) {
        // Login successful - call to appropriate handler
        onJudgeLogin(data.judge);
        setPin('');
      } else {
        setError(language === 'tl' ? 'Maling PIN' : data.message || 'Invalid PIN');
      }
    } catch (err) {
      setError(language === 'tl' ? 'Network error. Subukan muli.' : 'Network error. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleAdminAuth = () => {
    // Simple PIN authentication (in production, this should be secure)
    const adminPin = '1234'; // Change this in production
    if (pin === adminPin) {
      setIsAdmin(true);
      setShowAuth(false);
    } else {
      alert('Invalid PIN. Please try again.');
    }
  };

  const handleJudgeLogin = (judgeData) => {
    setCurrentJudge(judgeData);
    setShowJudgeLoginState(false);
    setShowAuth(false);
  };

  const handleLogout = () => {
    setIsAdmin(false);
    setShowAuth(true);
    setCurrentJudge(null);
    setShowJudgeLoginState(false);
    setAuthPin('');
  };

  const handleBackToAuth = () => {
    setShowAuth(true);
    setShowJudgeLoginState(false);
    setCurrentJudge(null);
  };

  return (
    <div className="judge-login-container">
      <div className="judge-login-card">
        <div className="auth-header">
          <div className="header-icon">
            <i className="fi fi-rr-shield-check"></i>
          </div>
          <h1>Tabulator System</h1>
          <p>Choose your login type</p>
          <div className="language-selector">
            <label htmlFor="language">Language:</label>
            <select 
              id="language"
              value={language}
              onChange={(e) => setLanguage(e.target.value)}
              className="language-dropdown"
            >
              <option value="en">English</option>
              <option value="tl">Filipino</option>
            </select>
          </div>
        </div>
        <div className="auth-options">
          <div className="auth-option" onClick={() => setShowJudgeLoginState(false)}>
            <div className="option-icon">
              <i className="fi fi-rr-shield-check"></i>
            </div>
            <div className="option-content">
              <h3>{language === 'tl' ? 'Admin na Access' : 'Admin Access'}</h3>
              <p>{language === 'tl' ? 'System administrator login' : 'System administrator login'}</p>
            </div>
          </div>

          <div className="auth-option" onClick={() => setShowJudgeLoginState(true)}>
            <div className="option-icon">
              <i className="fi fi-rr-shield-check"></i>
            </div>
            <div className="option-content">
              <h3>{language === 'tl' ? 'Judge na Login' : 'Judge Access'}</h3>
              <p>{language === 'tl' ? 'Enter your judge PIN' : 'Enter your judge PIN'}</p>
            </div>
          </div>
        </div>

        {!showJudgeLogin ? (
          // Admin Login Form
          <div className="auth-form">
            <label htmlFor="adminPin">{language === 'tl' ? 'Enter Admin PIN:' : 'Enter Admin PIN:'}</label>
            <input
              type="password"
              id="adminPin"
              value={pin}
              onChange={(e) => setPin(e.target.value)}
              placeholder={language === 'tl' ? 'Enter 4-digit PIN' : 'Enter 4-digit PIN'}
              maxLength="4"
              onKeyPress={(e) => e.key === 'Enter' && handleAdminAuth()}
            />
            <button className="auth-submit-btn" onClick={handleAdminAuth}>
              <i className="fi fi-rr-lock"></i>
              {language === 'tl' ? 'Login as Admin' : 'Login as Admin'}
            </button>
          </div>
        ) : (
          // Judge Login Form - Same design as admin
          <div className="auth-form">
            <label htmlFor="judgePin">{language === 'tl' ? 'Enter Judge PIN:' : 'Enter Judge PIN:'}</label>
            <input
              type="password"
              id="judgePin"
              value={pin}
              onChange={(e) => setPin(e.target.value)}
              placeholder={language === 'tl' ? 'Enter 4-digit PIN' : 'Enter 4-digit PIN'}
              maxLength="4"
              onKeyPress={(e) => e.key === 'Enter' && handleLogin()}
            />
            <button className="auth-submit-btn" onClick={handleLogin}>
              <i className="fi fi-rr-lock"></i>
              {language === 'tl' ? 'Login as Judge' : 'Login as Judge'}
            </button>
          </div>
        )}

        <div className="auth-footer">
          <p>{language === 'tl' ? 'Default Admin PIN: 1234' : 'Default Admin PIN: 1234'}</p>
          <p className="security-note">{language === 'tl' ? '⚠️ Baguhin ito sa production' : '⚠️ Change this in production'}</p>
          <div className="demo-pins">
            <p><strong>{language === 'tl' ? 'Demo Judge PINs:' : 'Demo Judge PINs:'}</strong> 2847, 9156, 3729, 6481</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default JudgeLogin;
